const s = $('Collect Stats').first().json;
const execs = $('Failed Executions').first().json;
const wfs = $('Workflow Names').first().json;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const n = v => Number(v || 0);
const trend = (now, prev) => {
  const d = n(now) - n(prev);
  return d === 0 ? '(= gestern)' : d > 0 ? `(▲ +${d})` : `(▼ ${d})`;
};
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];

// Fehlgeschlagene n8n-Ausführungen der letzten 24h, gruppiert nach Workflow
const names = Object.fromEntries((wfs.data || []).map(w => [w.id, w.name]));
const since = Date.now() - 24 * 3600 * 1000;
const failed = (execs.data || []).filter(e => new Date(e.startedAt).getTime() >= since);
const byWf = {};
for (const e of failed) { const k = names[e.workflowId] || e.workflowId; byWf[k] = (byWf[k] || 0) + 1; }
const failedTop = Object.entries(byWf).sort((a, b) => b[1] - a[1]).slice(0, 3);
const apiDown = !!(execs.error || wfs.error);

const problems = n(s.high_risk_24h) + n(s.approvals_stale) + failed.length + n(s.runs_failed_24h) + n(s.error_events_24h);
const quiet = n(s.msgs_24h) === 0 && n(s.runs_24h) === 0;
const status = problems > 0 ? '🔴 Handlungsbedarf' : quiet ? '💤 Keine Aktivität' : '🟢 Alles im grünen Bereich';
const date = new Date().toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Berlin' });

const L = [`📊 <b>EMMA Daily Report</b> – ${date}`, `<b>${status}</b>`, ''];

if (quiet) {
  const last = s.last_msg_at ? new Date(s.last_msg_at).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }) : 'nie';
  L.push(`In den letzten 24h kam nichts rein. Letzte Nachricht: ${esc(last)}.`);
  L.push('👉 Prüfen, ob <b>EMMA_MASTER_ORCHESTRATOR</b> aktiv ist.');
} else {
  L.push(`💬 Nachrichten: <b>${n(s.msgs_24h)}</b> ${trend(s.msgs_24h, s.msgs_prev)}`);
  L.push(`⚙️ Engine-Läufe: <b>${n(s.runs_24h)}</b> ${trend(s.runs_24h, s.runs_prev)}`);
  const top = list(s.top_engines);
  if (top.length) L.push(`   ${top.map(t => `${esc(t.engine)} ${t.n}`).join(' · ')}`);
  if (n(s.leads_24h)) L.push(`🎯 Neue Leads: <b>${n(s.leads_24h)}</b>`);
}

if (n(s.high_risk_24h)) {
  L.push('', `⚠️ High-Risk: <b>${n(s.high_risk_24h)}</b>`);
  for (const h of list(s.high_risk_items)) L.push(`   • ${esc(h.engine)}: „${esc(h.input)}“`);
}
if (n(s.approvals_pending)) {
  L.push(`✅ Offene Freigaben: <b>${n(s.approvals_pending)}</b>` + (n(s.approvals_stale) ? ` (${n(s.approvals_stale)} älter als 48h!)` : ''));
}
if (n(s.tasks_open)) {
  L.push(`📋 Offene Aufgaben: <b>${n(s.tasks_open)}</b>` + (n(s.tasks_new_24h) ? ` (+${n(s.tasks_new_24h)} neu)` : ''));
  for (const t of list(s.oldest_tasks)) L.push(`   • ${esc(t.title)}`);
}
if (failed.length || n(s.runs_failed_24h) || n(s.error_events_24h)) {
  L.push('', `❌ Fehler: <b>${failed.length}</b> Ausführungen, ${n(s.runs_failed_24h)} Engine-Antworten unlesbar, ${n(s.error_events_24h)} Error-Events`);
  for (const [wf, c] of failedTop) L.push(`   • ${esc(wf)} ×${c}`);
}
const agenda = list(s.agenda);
if (agenda.length) {
  L.push('', '💬 <b>Emma möchte mit dir besprechen:</b>');
  for (const a of agenda) L.push(`   • ${esc(a.topic)}`);
}
L.push('', `🧠 Emma: ${n(s.cycles_24h)}× nachgedacht, ${n(s.memories_24h)} neue Erinnerungen, ${n(s.jarvis_24h)}× mit Jarvis beraten`);
if (s.last_thought) L.push(`   „${esc(s.last_thought)}“`);
if (s.next_wake) L.push(`   ⏰ Nächste Weckzeit: ${new Date(s.next_wake).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'short', hour: '2-digit', minute: '2-digit' })}`);
const BUDGET = 5;
const icons = { briefing: '📰', protokoll: '📒', wissen: '📚', entwurf: '✍️', kalender: '📅' };
const arts = list(s.artifacts);
L.push('', `🧾 Arbeitsspuren (24h): <b>${n(s.artifacts_24h)}</b>`);
for (const a of arts) L.push(`   ${icons[a.kind] || '•'} ` + (a.url ? `<a href="${esc(a.url)}">${esc(a.title)}</a>` : esc(a.title)));
if (!arts.length) L.push('   – noch keine Spuren. Sobald Emma denkt, erscheinen hier Notizen, Entwürfe und Termine.');
L.push('', `💶 KI-Budget: ${Number(s.spent_month || 0).toFixed(2).replace('.', ',')} € von ${BUDGET} € (${n(s.llm_calls_month)} Aufrufe diesen Monat)` + (Number(s.spent_month || 0) >= BUDGET ? ' – <b>Limit erreicht, Emma pausiert</b>' : ''));
if (n(s.tasks_open) || n(s.approvals_pending)) L.push('', 'Alles im Detail: /agenda');
if (apiDown) L.push('', 'ℹ️ n8n-API nicht erreichbar – Ausführungsfehler nicht geprüft.');

return [{ json: { report: L.join('\n') } }];
